# Write agent and package
dst = Path('/kaggle/working')
agent_code = gzip.decompress(base64.b64decode(AGENT_B64))
main_py = dst / 'main.py'
main_py.write_bytes(agent_code)
print(f'Wrote main.py: {len(agent_code)} bytes')

with tarfile.open(dst / 'submission.tar.gz', 'w:gz') as tar:
    tar.add(main_py, arcname='main.py')
main_py.unlink()

print(f'submission.tar.gz ready ({(dst / "submission.tar.gz").stat().st_size / 1024:.1f} KB)')